import { IUniform, Matrix4, Texture, Uniform, Vector2, Vector3 } from 'three'
import { BlackHoleParameters } from '@/core/renderables/BlackHole/BlackHoleParameters'
import { config } from '@/core/framework/config'
import { createSkyUniforms } from '@/core/materials/shaders/lib/chunks/SkySample'

/**
 * Шейдер чёрной дыры, этап 3: лензирование Шварцшильда + аккреционный диск
 *
 * Лензирование (этапы 2 и 4): уравнение Бине u''(φ) = −u + (3/2)·u² (rs = 1),
 * velocity Verlet по углу φ; для далёких лучей — LUT отклонения, запечённый
 * тем же интегратором и тем же dphi (обе ветки сходят в ноль на границе зоны)
 *
 * Диск (этап 3) — ТОНКИЙ: математическая плоскость, сэмплируемая в точках
 * пересечения геодезической с экваториальной плоскостью, front-to-back
 * накопление (до 4 видимых пересечений: прямое изображение, нижнее
 * лензированное, вклады фотонного кольца). Никакого объёмного марширования
 *
 * Шейдинг пересечения: профиль Шакуры–Сюняева T(r) = T_in·(r/r_in)^(−3/4),
 * аналитический планковский blackbody, доплер по ЛОКАЛЬНОМУ направлению
 * изогнутого луча (beaming I·δ^3 + сдвиг температуры), грав. покраснение
 * √(1−rs/r), дифференциальное вращение ω ∝ r^(−3/2) с двухслойным
 * кроссфейдом против намотки спирали
 *
 * Эмиссия диска пишется в HDR (> 1.0) — Bloom композера подхватывает её
 * по порогу 1.0; небо из общего чанка (SkySample) тоже способно превысить
 * 1.0 и блумить само
 */

/**
 * Фабрика uniforms — каждый материал получает собственные экземпляры
 * (защита от разделяемых Uniform-ссылок при спреде шаблона)
 */
export function createBlackHoleUniforms(parameters: BlackHoleParameters): Record<string, IUniform> {
  return {
    // ВАЖНО: имена crModelViewMatrix/crProjectionMatrix — не косметика.
    // WebGLRenderer безусловно перезаписывает uniforms с зарезервированными
    // именами (modelViewMatrix, projectionMatrix, modelMatrix, cameraPosition...)
    // своими значениями на каждом draw call, даже для RawShaderMaterial —
    // camera-relative матрицы с такими именами никогда не доедут до GPU
    crModelViewMatrix: new Uniform(new Matrix4()),
    crProjectionMatrix: new Uniform(new Matrix4()),
    localCameraPos: new Uniform(new Vector3()),
    logDepthBufFC: new Uniform(1),

    /** Перевод: объектные единицы Three.js → единицы rsVisual */
    invRsUnits: new Uniform(1 / parameters.rsVisualUnits),
    /** Перевод: единицы rsVisual → объектные единицы Three.js */
    rsUnits: new Uniform(parameters.rsVisualUnits),

    /** Радиус зоны симуляции в единицах rsVisual */
    simulationRs: new Uniform(parameters.simulationRs),

    /** Плоскость диска: нормаль и базис (из axialTilt), радиусы в единицах rsVisual */
    diskNormal: new Uniform(new Vector3(0, 1, 0)),
    diskTangentX: new Uniform(new Vector3(1, 0, 0)),
    diskTangentY: new Uniform(new Vector3(0, 0, -1)),
    diskInnerRs: new Uniform(parameters.diskInnerRs),
    diskOuterRs: new Uniform(parameters.diskOuterRs),

    /** Наличие и параметры диска */
    uHasDisk: new Uniform(parameters.hasDisk ? 1 : 0),
    uDiskTemperature: new Uniform(parameters.temperature),
    uDiskIntensity: new Uniform(parameters.diskIntensity),
    uDopplerStrength: new Uniform(parameters.dopplerStrength),
    uPhotonRingIntensity: new Uniform(parameters.photonRingIntensity),
    uNoiseScale: new Uniform(parameters.diskNoiseScale),
    uNoiseOffset: new Uniform(new Vector2()),
    noiseMap: new Uniform<Texture | null>(null),

    /** LUT полного отклонения для дальних лучей (см. deflectionLut.ts) */
    deflectionLut: new Uniform<Texture | null>(null),
    /** LUT наружной добавки δ(b) для лучей геодезической ветки, вошедших снаружи */
    outsideLut: new Uniform<Texture | null>(null),

    /** Время симуляции в днях (свёрнутое на CPU, см. BlackHoleMaterial.update) */
    uTime: new Uniform(0),
    /** Период обращения внутреннего края диска, дни (rotationPeriod) */
    uRotationPeriod: new Uniform(Math.max(parameters.rotationPeriod, 1e-3)),

    /** Шаг интегрирования по углу, рад (конфиг качества) */
    uDphi: new Uniform(config('blackHole.integrationDphi')),
    /** Дебаг: 0 — лензирование выключено (passthrough этапа 1), 1 — включено */
    uLensing: new Uniform(1),

    /**
     * Копия кадра от BlackHolePass: побег луча читает пиксель кадра по
     * спроецированному направлению (тела, лучи и туманности за дырой), кубмапа —
     * подстраховка за экраном и для объектов перед плоскостью сближения.
     * uSceneEnabled 0 (рендер вне пасса) — только кубмапа
     */
    uSceneColor: new Uniform<Texture | null>(null),
    uSceneDepth: new Uniform<Texture | null>(null),
    /** Слой видимого неба кадра (SkyLayer): вычитается из копии в ветке кадра */
    uSkyLayer: new Uniform<Texture | null>(null),
    uSceneLogFarFactor: new Uniform(1),
    uSceneEnabled: new Uniform(0),
    /** Дебаг: подкраска пикселей по числу пересечений плоскости диска */
    uDebugCrossings: new Uniform(0),

    /**
     * Фоновая кубмапа: приходит не из scene.background (его больше не
     * назначают — фон рисует собственный полноэкранный проход), а из
     * ResourceObserver.sceneBackground, обновляется каждый кадр
     */
    skybox: new Uniform(null),

    /**
     * Юниформы неба — общий набор всех мест чтения фона (SkySample): в режиме
     * gaia те же экземпляры, что у фонового прохода, расхождение невозможно
     */
    ...createSkyUniforms()
  }
}

export const BlackHoleShaderTemplate = {
  vertexShader: /* glsl */ `
    precision highp float;

    uniform mat4 crModelViewMatrix;
    uniform mat4 crProjectionMatrix;
    uniform vec3 localCameraPos;
    uniform float invRsUnits;

    in vec3 position;

    out vec3 vPositionRs;
    out vec3 vCameraRs;
    out float vFragDepth;

    void main() {
      vec4 mvPosition = crModelViewMatrix * vec4(position, 1.0);
      gl_Position = crProjectionMatrix * mvPosition;

      vPositionRs = position * invRsUnits;
      vCameraRs = localCameraPos * invRsUnits;

      vFragDepth = 1.0 + gl_Position.w;
    }
  `,
  fragmentShader: /* glsl */ `
    precision highp float;

    uniform mat4 crModelViewMatrix;
    uniform float logDepthBufFC;
    uniform float rsUnits;
    uniform float simulationRs;

    uniform vec3 diskNormal;
    uniform vec3 diskTangentX;
    uniform vec3 diskTangentY;
    uniform float diskInnerRs;
    uniform float diskOuterRs;

    uniform float uHasDisk;
    uniform float uDiskTemperature;
    uniform float uDiskIntensity;
    uniform float uDopplerStrength;
    uniform float uPhotonRingIntensity;
    uniform float uNoiseScale;
    uniform vec2 uNoiseOffset;
    uniform sampler2D noiseMap;
    uniform highp sampler2D deflectionLut;
    uniform highp sampler2D outsideLut;

    uniform float uTime;
    uniform float uRotationPeriod;

    uniform float uDphi;
    uniform float uLensing;
    uniform float uDebugCrossings;

    uniform samplerCube skybox;
    // Копия кадра от BlackHolePass (см. sampleBackground)
    uniform sampler2D uSceneColor;
    uniform highp sampler2D uSceneDepth;
    // Слой видимого неба кадра (SkyLayer): вычитается из копии в ветке кадра
    uniform sampler2D uSkyLayer;
    uniform float uSceneLogFarFactor;
    uniform float uSceneEnabled;
    uniform mat4 crProjectionMatrix;

    #include <skySampleUniforms>
    #include <skySampleFunctions>

    in vec3 vPositionRs;
    in vec3 vCameraRs;
    in float vFragDepth;

    layout(location = 0) out vec4 fragColor;

    const float TWO_PI = 6.28318530718;
    // Потолок шагов — СТРАХОВКА от бесконечного цикла, а не рабочий предел:
    // типичный луч выходит за 60–140 шагов, рабочий ограничитель — PHI_MAX.
    // Связь несущая: дойти до PHI_MAX стоит PHI_MAX/uDphi шагов, и если
    // потолок ниже — он молча обрежет навивку и убьёт фотонное кольцо
    // (проверено: dphi 0.02 требует 471 шаг, при потолке 240 кольцо исчезает).
    // При шиппинговых PHI_MAX = 3π и dphi = 0.05 нужно ~189 шагов — 256 даёт
    // запас ~35%, не больше: подъём навивки до 6π пробовали и откатили
    // (дело было не в намотке, а в грубости углового шага у фотонной сферы),
    // так что запас под 6π не нужен, а компиляция под более высокий потолок
    // измеримо дороже (изолированный замер на RTX 5070 Ti, ANGLE D3D11:
    // 240→512 стоил +0.35 мс/проход, ~30%; пару 256 против 240 отдельно
    // не изолировали, число — оценка по этому замеру, не точная величина).
    // Если когда-нибудь уточнят dphi без подъёма потолка — сюда вернуться.
    // Закреплено tests/blackHole/IntegratorBudget.spec.ts.
    const int MAX_STEPS = 256;
    // 3π — приближение, а не точная граница захвата: лучи у критического
    // прицельного параметра навиваются много раз и всё равно уходят —
    // это и есть кольца высших порядков. Подъём до 4π и 6π при dphi = 0.05
    // пробовали — картинка не изменилась (дело было не в намотке, а в
    // грубости углового шага у фотонной сферы, см. MAX_STEPS выше)
    const float PHI_MAX = 9.42477796;
    // Граница LUT-ветки: дальше полное отклонение берётся из deflectionLut.
    // Геодезическая ветка даёт хорду + δ(b) из outsideLut, где δ печётся как
    // «полное − хорда этого же интегратора» — стык жёсткий, без кроссфейда
    // (см. deflectionLut.ts)
    const float WEAK_FIELD_B = 8.0;

    // Фон побега луча: пиксель КАДРА по спроецированному направлению — тела,
    // лучи и туманности за дырой лензируются сильным полем, а видимое в копии
    // небо заменяется небом по искривлённому лучу (вычитание слоя, см.
    // SkyLayer). Только небо — вне BlackHolePass, за экраном (и при p.w ≤ 0) и
    // для объекта перед плоскостью наибольшего сближения: он не за линзой и
    // копироваться не должен. dDx/dDy — производные побега, dPixDx/dPixDy —
    // неотклонённого луча пикселя (площадь пикселя и усиление звёзд)
    vec3 sampleBackground(vec3 direction, vec3 dDx, vec3 dDy, vec3 dPixDx, vec3 dPixDy) {
      // Explicit return branches avoid ANGLE/D3D11 X4000 on the function result.
      if (uSceneEnabled < 0.5) {
        return sampleSkyLensed(direction, dDx, dDy, dPixDx, dPixDy);
      } else {
        vec3 dirView = normalize(mat3(crModelViewMatrix) * direction);
        vec4 p = crProjectionMatrix * vec4(dirView, 0.0);
        vec2 uv = p.xy / max(p.w, 1e-6) * 0.5 + 0.5;
        if (p.w <= 0.0 || any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
          return sampleSkyLensed(direction, dDx, dDy, dPixDx, dPixDy);
        } else {
          // crModelViewMatrix camera-relative: столбец переноса — центр дыры в виде
          vec3 centerView = crModelViewMatrix[3].xyz;
          float tMid = dot(centerView, dirView);
          float z = texture(uSceneDepth, uv).r;
          float sceneT = z >= 1.0 - 1e-6 ? 1e30 : (exp2(z * uSceneLogFarFactor) - 1.0) / max(-dirView.z, 1e-6);
          if (sceneT < tMid) {
            return sampleSkyLensed(direction, dDx, dDy, dPixDx, dPixDy);
          } else {
            // max: под поглощающей туманностью копия = T·небо + свечение, разность ниже нуля
            vec4 layer = texture(uSkyLayer, uv);
            return max(texture(uSceneColor, uv).rgb - layer.rgb, vec3(0.0)) + layer.a * sampleSkyLensed(direction, dDx, dDy, dPixDx, dPixDy);
          }
        }
      }
    }

    // Аналитический планковский blackbody: CIE-аппроксимация локуса → XYZ → linear sRGB,
    // нормировка по максимальному каналу (яркость задаётся отдельно интенсивностью)
    vec3 blackbody(float t) {
      t = clamp(t, 1500.0, 20000.0);
      float u = (0.860117757 + 1.54118254e-4 * t + 1.28641212e-7 * t * t)
              / (1.0 + 8.42420235e-4 * t + 7.08145163e-7 * t * t);
      float v = (0.317398726 + 4.22806245e-5 * t + 4.20481691e-8 * t * t)
              / (1.0 - 2.89741816e-5 * t + 1.61456053e-7 * t * t);
      float x = 3.0 * u / (2.0 * u - 8.0 * v + 4.0);
      float y = 2.0 * v / (2.0 * u - 8.0 * v + 4.0);
      vec3 xyz = vec3(x / y, 1.0, (1.0 - x - y) / y);
      vec3 rgb = mat3(
        3.2404542, -0.9692660, 0.0556434,
        -1.5371385, 1.8760108, -0.2040259,
        -0.4985314, 0.0415560, 1.0572252
      ) * xyz;
      rgb = max(rgb, vec3(0.0));
      return rgb / max(max(rgb.r, rgb.g), max(rgb.b, 1e-4));
    }

    // Турбулентность диска в координатах (азимут в оборотах, log r) с
    // дифференциальным вращением домена. Азимутальные множители ЦЕЛЫЕ —
    // условие бесшовности по θ при REPEAT-тайлинге текстуры
    float diskNoise(float turns, float rc, float tau) {
      float omega = TWO_PI / uRotationPeriod * pow(rc / diskInnerRs, -1.5);
      float x = turns - tau * omega / TWO_PI;
      vec2 uv = vec2(x * 3.0, log(rc) * 5.0 * uNoiseScale) + uNoiseOffset;
      // анизотропия: низкая частота по θ, высокая по r — азимутальные прожилки
      return texture(noiseMap, uv).r * 0.62
           + texture(noiseMap, uv * vec2(2.0, 2.3) + vec2(0.37, 0.71)).g * 0.38;
    }

    // Шейдинг одного пересечения геодезической с плоскостью диска.
    // localDir — локальное направление ИЗОГНУТОГО луча в точке пересечения
    vec4 shadeDisk(vec3 cp, vec3 localDir, float phiAcc) {
      float rc = length(cp);
      float theta = atan(dot(cp, diskTangentY), dot(cp, diskTangentX));
      float turns = theta / TWO_PI + 0.5;

      // двухслойный кроссфейд против намотки спирали дифференциальным вращением:
      // каждый слой «сбрасывается» в ненамотанное состояние, пока невидим
      float crossfadePeriod = uRotationPeriod * 6.0;
      float w = abs(fract(uTime / crossfadePeriod) * 2.0 - 1.0);
      float n1 = diskNoise(turns, rc, mod(uTime, crossfadePeriod) - 0.5 * crossfadePeriod);
      float n2 = diskNoise(turns, rc, mod(uTime + 0.5 * crossfadePeriod, crossfadePeriod) - 0.5 * crossfadePeriod);
      float n = mix(n1, n2, w);

      // мягкие края кольца
      float edge = smoothstep(diskInnerRs, diskInnerRs * 1.25, rc)
                 * (1.0 - smoothstep(diskOuterRs * 0.78, diskOuterRs, rc));

      // Шакура–Сюняев: температура падает наружу
      float temperature = uDiskTemperature * pow(rc / diskInnerRs, -0.75);

      // кеплеровская скорость газа и доплер по локальному направлению луча;
      // фотон летит К НАБЛЮДАТЕЛЮ против хода трассировки: −localDir
      float beta = sqrt(0.5 / rc);
      float gamma = inversesqrt(max(1.0 - beta * beta, 1e-3));
      vec3 velocityDir = normalize(cross(diskNormal, cp));
      float cosAngle = dot(velocityDir, -localDir);
      float doppler = 1.0 / (gamma * (1.0 - beta * cosAngle));

      // гравитационное покраснение
      float gravShift = sqrt(max(1.0 - 1.0 / rc, 0.0));

      // сдвиг температуры (цвета) и релятивистский beaming (яркости),
      // оба под художественной гайкой dopplerStrength
      float observedT = temperature * pow(doppler, uDopplerStrength) * gravShift;
      float beaming = pow(doppler, 3.0 * uDopplerStrength);

      // фотонное кольцо возникает само из навитых лучей; гайка — его звонкость
      float ringBoost = 1.0 + uPhotonRingIntensity * 1.6 * smoothstep(4.0, 6.0, phiAcc);

      vec3 color = blackbody(observedT)
                 * uDiskIntensity
                 * pow(diskInnerRs / rc, 2.2)
                 * beaming * gravShift * gravShift
                 * ringBoost
                 * (0.4 + 0.8 * n);

      float alpha = clamp(edge * (0.35 + 0.85 * n), 0.0, 1.0) * 0.85 + 0.1 * edge;

      return vec4(color, clamp(alpha, 0.0, 0.95));
    }

    // Честное интегрирование уравнения Бине в плоскости геодезической
    // с накоплением пересечений диска front-to-back. Фон здесь не читается:
    // производные направления побега нужны в равномерном потоке (см. main)
    vec3 traceGeodesic(vec3 cameraRs, vec3 rayDir, float tEnter, float b,
                       out int crossings, out float opacity, out vec3 escape, out bool escaped) {
      crossings = 0;
      opacity = 0.0;
      // Захваченный луч: значение не читается, нужно лишь для производных соседей
      escape = rayDir;
      escaped = false;

      vec3 p0 = cameraRs + tEnter * rayDir;
      float r0 = length(p0);

      // базис плоскости геодезической (Грам-Шмидт)
      vec3 e1 = p0 / r0;
      float radial = dot(rayDir, e1);
      vec3 e2v = rayDir - radial * e1;
      float tangential = length(e2v);

      // вырожденный луч точно в центр / из центра
      if (tangential < 1e-4) {
        escaped = radial > 0.0;
        return vec3(0.0);
      }

      vec3 e2 = e2v / tangential;

      // начальные условия Бине: u = 1/r, u' = du/dφ.
      // Вход снаружи (tEnter > 0): плоское направление отрезка «камера → сфера»
      // перецеливается в локальное направление луча с тем же b:
      // sin θ_loc = (b/r)·√(1 − rs/r), u' = cot θ_loc·√(1 − rs/r)/r — иначе
      // трассируется луч с b на 1.9 % больше (зеркало: deflectionLut.entryState).
      // Камера внутри сферы: направление пикселя и есть локальное, условие прежнее
      bool enteredFromOutside = tEnter > 0.0;
      float u = 1.0 / r0;
      float du = enteredFromOutside
        ? sqrt(max(1.0 - tangential * tangential * (1.0 - 1.0 / r0), 0.0)) / (tangential * r0)
        : -radial / (r0 * tangential);
      float phi = 0.0;
      vec3 prev = p0;

      vec3 accumulated = vec3(0.0);

      for (int i = 0; i < MAX_STEPS; i++) {
        if (phi > PHI_MAX) break;                                // навивка — захват

        // velocity Verlet: одно вычисление правой части на шаг, без дрейфа
        float a0 = -u + 1.5 * u * u;
        float u1 = u + du * uDphi + 0.5 * a0 * uDphi * uDphi;
        float a1 = -u1 + 1.5 * u1 * u1;
        du += 0.5 * (a0 + a1) * uDphi;
        u = u1;
        phi += uDphi;

        if (u > 1.0) break;                                      // захват горизонтом
        u = max(u, 1e-5);

        float r = 1.0 / u;
        vec3 pos = (cos(phi) * e1 + sin(phi) * e2) * r;

        // пересечение плоскости диска: линейная интерполяция точки между шагами
        float h0 = dot(prev, diskNormal);
        float h1 = dot(pos, diskNormal);
        if (uHasDisk > 0.5 && h0 * h1 < 0.0 && crossings < 4 && opacity < 0.99) {
          float tc = h0 / (h0 - h1);
          vec3 crossPoint = mix(prev, pos, tc);
          float rc = length(crossPoint);
          if (rc > diskInnerRs && rc < diskOuterRs) {
            crossings++;
            vec4 sample_ = shadeDisk(crossPoint, normalize(pos - prev), phi);
            accumulated += (1.0 - opacity) * sample_.a * sample_.rgb;
            opacity += (1.0 - opacity) * sample_.a;
          }
        }

        // побег из зоны симуляции: финальное направление → кубмапа.
        // Луч, вошедший снаружи, доворачивается к центру на δ(b) из OutsideLut —
        // наружную часть отклонения (полное − хорда), которую прямые отрезки
        // вне сферы не набирают; на границе с LUT-веткой суммы совпадают
        if (r > simulationRs && dot(pos, pos) > dot(prev, prev)) {
          escape = normalize(pos - prev);
          if (enteredFromOutside) {
            float delta = texture(outsideLut, vec2((0.5 + (b / simulationRs) * 255.0) / 256.0, 0.5)).r;
            vec3 toCenter = -pos - dot(-pos, escape) * escape;
            float side = length(toCenter);
            if (side > 1e-6) {
              vec3 inward = toCenter / side;
              escape = normalize(cos(delta) * escape + sin(delta) * inward);
            }
          }
          escaped = true;
          return accumulated;
        }

        prev = pos;
      }

      // захват горизонтом: сквозь полупрозрачный диск просвечивает чернота
      return accumulated;
    }

    void main() {
      vec3 cameraRs = vCameraRs;
      vec3 rayDir = normalize(vPositionRs - cameraRs);

      // Производные неотклонённого луча пикселя — до ветвлений: площадь
      // пикселя и усиление звёзд линзой (sampleSkyLensed). Меш не вращается —
      // объектные направления совпадают с мировыми
      vec3 rayDx = dFdx(rayDir);
      vec3 rayDy = dFdy(rayDir);

      // геометрия прицельного параметра (дыра в нуле объектного пространства)
      float tMid = -dot(cameraRs, rayDir);
      float b2 = dot(cameraRs, cameraRs) - tMid * tMid;
      float b = sqrt(max(b2, 0.0));

      bool cameraInside = dot(cameraRs, cameraRs) < simulationRs * simulationRs;

      // дистанция входа луча в зону симуляции (0 — камера внутри)
      float tEnter = cameraInside
        ? 0.0
        : max(tMid - sqrt(max(simulationRs * simulationRs - b2, 0.0)), 0.0);

      // граница аналитической ветки: при наличии диска отодвигается за его
      // внешний край (радиус пересечения плоскости ≥ прицельного параметра,
      // т.е. b > diskOuter + запас гарантирует отсутствие попаданий в диск)
      float weakFieldB = uHasDisk > 0.5
        ? max(WEAK_FIELD_B, diskOuterRs + 1.5)
        : WEAK_FIELD_B;

      vec3 color = vec3(0.0);
      int crossings = 0;
      float opacity = 0.0;
      vec3 escape = rayDir;
      bool escaped = true;

      if (uLensing < 0.5) {
        // дебаг-режим этапа 1: неизогнутый passthrough (эталон бесшовности)
        escape = rayDir;
      } else if (!cameraInside && b > weakFieldB) {
        // LUT-ветка: ПОЛНОЕ отклонение луча из таблицы (deflectionLut.ts,
        // старт интегратора далеко за зоной). На краю зоны α = 2/R и далее,
        // снаружи меша ту же величину по ряду дальнего поля даёт экранный
        // проход GravitationalLensEffect — поле сдвига через кромку гладкое.
        // Домен таблицы [WEAK_FIELD_B, simulationRs]; при диске ветка
        // включается позже (weakFieldB отодвинут за диск) — просто читаем
        // таблицу с большего t
        float t = (b - WEAK_FIELD_B) / (simulationRs - WEAK_FIELD_B);
        // Сетка LUT лежит на краях домена: узел i стоит в t = i/255, а тексель
        // i центрирован в (i + 0.5)/256 — коррекция ниже совмещает их, чтобы
        // t = 0 читал ровно узел b = WEAK_FIELD_B (стык с геодезической веткой),
        // а t = 1 — ровно узел на краю зоны, где полное отклонение продолжает
        // ряд дальнего поля экранного прохода. 255.0/256.0 — это (SIZE-1)/SIZE
        float alphaIn = texture(deflectionLut, vec2((0.5 + t * 255.0) / 256.0, 0.5)).r;
        vec3 inward = -normalize(cameraRs + tMid * rayDir);
        escape = cos(alphaIn) * rayDir + sin(alphaIn) * inward;
      } else {
        color = traceGeodesic(cameraRs, rayDir, tEnter, b, crossings, opacity, escape, escaped);
      }

      // Производные побега — в равномерном потоке, после веток: внутри
      // ветвлений dFdx не определён, а фильтру звёзд нужен отпечаток пикселя
      vec3 escapeDx = dFdx(escape);
      vec3 escapeDy = dFdy(escape);

      // Меш описан вокруг сферы (MESH_MARGIN): границу зоны задаёт аналитический
      // b, а не грани — снаружи кадр сдвигает GravitationalLensEffect с b > R.
      // discard только после производных: иначе у четвёрок на кромке они рвутся
      if (!cameraInside && b > simulationRs) discard;

      if (escaped) color += (1.0 - opacity) * sampleBackground(escape, escapeDx, escapeDy, rayDx, rayDy);

      // дебаг-визуализация пересечений кольца диска: 1 — красный, 2 — зелёный, 3+ — синий
      if (uDebugCrossings > 0.5 && crossings > 0) {
        vec3 tint = crossings == 1 ? vec3(1.0, 0.2, 0.2)
                  : crossings == 2 ? vec3(0.2, 1.0, 0.2)
                  : vec3(0.3, 0.4, 1.0);
        color = mix(color, tint, 0.6);
      }

      fragColor = vec4(color, 1.0);

      // ── Логарифмическая глубина ──
      // снаружи — передняя поверхность сферы (точка входа луча),
      // внутри при взгляде к дыре — плоскость сближения: тела за ней уже
      // попадают в sampleBackground, перед ней остаются в основном кадре
      float wEye;
      if (cameraInside && tMid > 0.0) {
        vec3 rayView = mat3(crModelViewMatrix) * rayDir;
        wEye = 1.0 + tMid * rsUnits * max(-rayView.z, 0.0);
      } else if (cameraInside) {
        wEye = vFragDepth;
      } else {
        vec3 entryObjectSpace = (cameraRs + tEnter * rayDir) * rsUnits;
        vec4 mvEntry = crModelViewMatrix * vec4(entryObjectSpace, 1.0);
        wEye = 1.0 - mvEntry.z;
      }
      float depth = log2(max(wEye, 1e-6)) * logDepthBufFC * 0.5;
      if (cameraInside && tMid <= 0.0 && uSceneEnabled > 0.5) {
        // От дыры: цвет заменяется, но глубина поверхности нужна атмосфере.
        // Читается безопасная копия того же пикселя, без фильтрации границ
        depth = min(depth, texelFetch(uSceneDepth, ivec2(gl_FragCoord.xy), 0).r);
      }
      gl_FragDepth = depth;
    }
  `
}

import {
  BackSide,
  Camera,
  CubeTexture,
  GLSL3,
  Matrix4,
  Mesh,
  OrthographicCamera,
  PerspectiveCamera,
  RawShaderMaterial,
  Texture,
  Vector3
} from 'three'
import { degToRad } from 'three/src/math/MathUtils'
import { config } from '@/core/framework/config'
import { BlackHoleParameters } from '@/core/renderables/BlackHole/BlackHoleParameters'
import { blackHoleDiskIntensity } from '@/core/renderables/BlackHole/diskEmission'
import { BlackHoleNoiseTexture } from '@/core/renderables/BlackHole/BlackHoleNoiseTexture'
import { BlackHoleShaderTemplate, createBlackHoleUniforms } from '@/core/renderables/BlackHole/BlackHoleShaderTemplate'
import { createDeflectionLutTexture, createOutsideLutTexture } from '@/core/renderables/BlackHole/deflectionLut'
import { AbstractShader } from '@/core/materials/shaders/AbstractShader'

/**
 * Материал чёрной дыры (этапы 1–3)
 *
 * RawShaderMaterial + GLSL3 с собственными модельными матрицами:
 * camera-relative паттерн — трансляции вычитаются на CPU в float64,
 * в шейдер попадают малые числа (uniforms названы crModelViewMatrix /
 * crProjectionMatrix — зарезервированные имена перезаписываются рендерером)
 *
 * Меш непрозрачен и пишет глубину — отдельный композитинг-пасс не нужен,
 * фон берётся из кубмапы сцены, Bloom/ACES обрабатывают дыру в общем пайплайне
 *
 * side: BackSide — камера может находиться внутри зоны симуляции
 */
class BlackHoleMaterial extends RawShaderMaterial {
  public readonly parameters: BlackHoleParameters

  private readonly _modelViewMatrix: Matrix4 = new Matrix4()
  private readonly _rotationOnlyView: Matrix4 = new Matrix4()
  private readonly _crModelMatrix: Matrix4 = new Matrix4()
  private readonly _localCameraPos: Vector3 = new Vector3()

  public constructor(parameters: BlackHoleParameters) {
    super({
      glslVersion: GLSL3,
      uniforms: createBlackHoleUniforms(parameters),
      // RawShaderMaterial собирается напрямую, минуя конструктор AbstractShader —
      // #include резолвится вручную тем же статическим методом, что и у
      // собственного фонового прохода (SkyboxBackground). Оба шейдера прогоняются
      // через prepareSource: непрогнанный вершинник с любым будущим #include
      // молча раскрылся бы в пустоту вместо кода
      vertexShader: AbstractShader.prepareSource(BlackHoleShaderTemplate.vertexShader),
      fragmentShader: AbstractShader.prepareSource(BlackHoleShaderTemplate.fragmentShader),

      side: BackSide,
      transparent: false,
      depthWrite: true,
      depthTest: true
    })

    this.parameters = parameters
    this.name = 'BlackHoleMaterial'

    // базис плоскости диска из axialTilt физического слоя; статичен —
    // меш не вращается, наклон живёт целиком в uniforms (см. BlackHole.__setup)
    const tiltRad: number = degToRad(parameters.axialTilt)
    const cos: number = Math.cos(tiltRad)
    const sin: number = Math.sin(tiltRad)
    this.uniforms.diskNormal.value.set(0, cos, sin)
    this.uniforms.diskTangentX.value.set(1, 0, 0)
    this.uniforms.diskTangentY.value.set(0, sin, -cos)

    // общая noise-текстура (одна на приложение) + seed-зависимое смещение UV
    this.uniforms.noiseMap.value = BlackHoleNoiseTexture.get()
    const seed: number = parameters.diskNoiseSeed
    this.uniforms.uNoiseOffset.value.set(
      seed * 0.7548776662 - Math.floor(seed * 0.7548776662),
      seed * 0.5698402909 - Math.floor(seed * 0.5698402909)
    )

    // Таблицы отклонения: свои на материал — у каждой дыры свой simulationRs.
    // δ(b) печётся против хорды с тем же dphi, что живой интегратор: это
    // несущий инвариант стыка ветвей (см. deflectionLut.ts)
    this.uniforms.deflectionLut.value = createDeflectionLutTexture(
      parameters.simulationRs,
      config('blackHole.integrationDphi')
    )
    this.uniforms.outsideLut.value = createOutsideLutTexture(
      parameters.simulationRs,
      config('blackHole.integrationDphi')
    )
  }

  /**
   * Покадровое обновление uniforms (вызывается из onBeforeRender —
   * матрицы камеры и меша гарантированно актуальны для текущего кадра)
   * @param mesh Меш bounding-сферы зоны симуляции
   * @param camera Камера текущего рендер-прохода. Тип — базовый `Camera`:
   *   используются только `matrixWorld`, `matrixWorldInverse`, `projectionMatrix`
   *   и (там, где он есть) `far`, поэтому сужать до `PerspectiveCamera` нечем —
   *   а `onBeforeRender` отдаёт именно `Camera`
   * @param background Фоновая кубмапа сцены: приходит не из scene.background
   *   (его больше не назначают — фон рисует собственный проход), а из
   *   ResourceObserver.sceneBackground, передаёт BlackHole.onBeforeRender
   * @param epoch Эпоха симуляции (дни), кэшированная BlackHole.updateObject
   */
  public update(mesh: Mesh, camera: Camera, background: CubeTexture | null, epoch: number): void {
    const mw: number[] = mesh.matrixWorld.elements
    const cw: number[] = camera.matrixWorld.elements

    // ── 1. Camera-relative модельная матрица (трансляция в float64 на CPU) ──
    this._crModelMatrix.copy(mesh.matrixWorld)
    this._crModelMatrix.elements[12] = mw[12] - cw[12]
    this._crModelMatrix.elements[13] = mw[13] - cw[13]
    this._crModelMatrix.elements[14] = mw[14] - cw[14]

    // ── 2. Camera-relative modelViewMatrix (view без трансляции) ──
    this._rotationOnlyView.copy(camera.matrixWorldInverse)
    this._rotationOnlyView.elements[12] = 0
    this._rotationOnlyView.elements[13] = 0
    this._rotationOnlyView.elements[14] = 0

    this._modelViewMatrix.multiplyMatrices(this._rotationOnlyView, this._crModelMatrix)
    this.uniforms.crModelViewMatrix.value.copy(this._modelViewMatrix)

    // ── 3. Проекция без изменений ──
    this.uniforms.crProjectionMatrix.value.copy(camera.projectionMatrix)

    // ── 4. Позиция камеры в объектном пространстве меша (float64 на CPU) ──
    // меш не вращается и не масштабируется, поэтому достаточно вычитания трансляции
    this._localCameraPos.set(cw[12] - mw[12], cw[13] - mw[13], cw[14] - mw[14])
    this.uniforms.localCameraPos.value.copy(this._localCameraPos)
    this.uniforms.uDiskIntensity.value = blackHoleDiskIntensity(this.parameters, this._localCameraPos.length())

    // ── 5. Логарифмическая глубина ──
    // `far` объявлен не в базовой Camera, а в Perspective/Orthographic; для
    // проекции без него берётся заведомо больший предел — ровно то, что раньше
    // давала ветка `?? 1e10` под кастом к PerspectiveCamera
    const far: number =
      camera instanceof PerspectiveCamera || camera instanceof OrthographicCamera ? camera.far : 1e10
    this.uniforms.logDepthBufFC.value = 2.0 / (Math.log(far + 1.0) / Math.LN2)

    // ── 6. Фоновая кубмапа — та же текстура, что рисует собственный фоновый проход ──
    // присваивание ссылки бесплатно; автоматически подхватит будущий процедурный фон
    this.uniforms.skybox.value = background

    // ── 7. Время диска: эпоха симуляции (дни), свёрнутая на CPU в float64 ──
    // по кратному периоду внутреннего края — фазы дифференциального вращения
    // не теряют точность в f32; диск ускоряется вместе со временем симуляции
    const wrap: number = this.parameters.rotationPeriod * 16384
    this.uniforms.uTime.value = epoch - Math.floor(epoch / wrap) * wrap
  }

  /** Копия кадра и слой неба от BlackHolePass (см. uSceneEnabled в шаблоне) */
  public bindSceneFrame(sceneColor: Texture, sceneDepth: Texture, skyLayer: Texture, logFarFactor: number): void {
    this.uniforms.uSceneColor.value = sceneColor
    this.uniforms.uSceneDepth.value = sceneDepth
    this.uniforms.uSkyLayer.value = skyLayer
    this.uniforms.uSceneLogFarFactor.value = logFarFactor
    this.uniforms.uSceneEnabled.value = 1
  }

  public unbindSceneFrame(): void {
    this.uniforms.uSceneColor.value = null
    this.uniforms.uSceneDepth.value = null
    this.uniforms.uSkyLayer.value = null
    this.uniforms.uSceneEnabled.value = 0
  }

  /**
   * LUT живёт только в юниформе этого материала: штатный dispose
   * RawShaderMaterial текстуры юниформов не разбирает, без override она
   * утекала бы на каждой пересборке сцены
   */
  public override dispose(): void {
    this.uniforms.deflectionLut.value?.dispose()
    this.uniforms.outsideLut.value?.dispose()
    super.dispose()
  }
}

export { BlackHoleMaterial }

import {
  BufferGeometry,
  Camera,
  Intersection,
  Mesh,
  Raycaster,
  Scene,
  Sphere,
  SphereGeometry,
  Texture,
  Vector3,
  WebGLRenderer
} from 'three'
import { Actor } from '@/core/models/Actor'
import { BlackHoleParameters } from '@/core/renderables/BlackHole/BlackHoleParameters'
import { BlackHoleMaterial } from '@/core/renderables/BlackHole/BlackHoleMaterial'
import { UpdateContext } from '@/core/UpdateContext'
import { ResourceObserver } from '@/core/services/ResourceObserver'
import type { LensEntry, LensRegistry } from '@/core/services/LensRegistry'
import { toThreeJSUnits } from '@/core/helpers/scaling'
import { BLACK_HOLE_LAYER, type SceneFrameConsumer } from '@/core/graphic/passes/DepthVolume'

/**
 * Чёрная дыра (уровень L0): bounding-сфера зоны симуляции лензирования
 *
 * Геометрия — сфера радиусом simulationRadius; шейдер исполняется только
 * на покрытых ею пикселях. Меш НИКОГДА не вращается (в отличие от Planet/Star):
 * объектные направления должны совпадать с мировыми для прямого сэмплирования
 * фоновой кубмапы; наклон диска (axialTilt) уйдёт в uniform на этапе 3
 *
 * Фоновую кубмапу берёт из ResourceObserver.sceneBackground, а не из
 * scene.background: собственный фоновый проход (SkyboxBackground) снял
 * присвоение scene.background, и оно теперь всегда null
 */
/**
 * Меш описан вокруг аналитической сферы зоны: многогранник 64×32 лежит внутри
 * неё до 0.5 % радиуса, и без запаса между гранями и сферой оставалась бы
 * полоска фона без сдвига (снаружи проход сдвигает только при b > R).
 * Лишнее фрагментник режет discard по b > simulationRs
 */
export const MESH_MARGIN: number = 1.008

class BlackHole extends Mesh implements SceneFrameConsumer {
  public model: Actor
  declare public geometry: BufferGeometry
  declare public material: BlackHoleMaterial

  public readonly parameters: BlackHoleParameters

  private static readonly _clickSphere: Sphere = new Sphere()
  private static readonly _clickPoint: Vector3 = new Vector3()

  private _epoch: number = 0

/** Запись в реестре линз: снимается в dispose */
  private lensEntry: LensEntry | null = null

  public constructor(
    model: Actor,
    private readonly resourceObserver: ResourceObserver,
    private readonly lensRegistry: LensRegistry | null = null
  ) {
    super()
    this.model = model
    this.parameters = new BlackHoleParameters(model)

    this.__setup()

    // Дальнее поле снаружи меша рисует экранный проход по этой записи;
    // видимость меша (LOD) он читает сам
    if (this.lensRegistry) {
      this.lensEntry = {
        object: this,
        rsUnits: toThreeJSUnits(this.parameters.rsVisual),
        simulationRadiusUnits: this.parameters.simulationRadiusUnits,
        background: () => this.resourceObserver.sceneBackground
      }
      this.lensRegistry.register(this.lensEntry)
    }
  }

  /** Копия кадра и слой неба от BlackHolePass: побег луча читает кадр, а не только небо */
  public bindSceneFrame(sceneColor: Texture, sceneDepth: Texture, skyLayer: Texture, logFarFactor: number): void {
    this.material.bindSceneFrame(sceneColor, sceneDepth, skyLayer, logFarFactor)
  }

  public unbindSceneFrame(): void {
    this.material.unbindSceneFrame()
  }

  /** Снятие с реестра линз; геометрию и материал освобождает обход графа */
  public dispose(): void {
    if (this.lensEntry) {
      this.lensRegistry?.unregister(this.lensEntry)
      this.lensEntry = null
    }
  }

  __setup(): void {
    // сфера — лишь проекционная оболочка для фрагментного шейдера,
    // сегментация влияет только на гладкость силуэта зоны
    this.geometry = new SphereGeometry(this.parameters.simulationRadiusUnits * MESH_MARGIN, 64, 32)
    this.material = new BlackHoleMaterial(this.parameters)

    this.name = this.model.getAttribute('name', '') + 'BlackHole'
    this.userData.type = 'blackHole'
    // Рисует BlackHolePass после сцены и объёмов по копии кадра; основной
    // проход слой не видит, кликовый рейкастер включает его сам
    this.layers.set(BLACK_HOLE_LAYER)
    // клик-таргет — сфера зоны симуляции, не горизонт (спецификация §9)
    this.userData.clickable = true

    // обновление uniforms — строго в onBeforeRender, а не в updateObject:
    // three вызывает его в момент рендера, когда матрицы камеры и меша
    // актуальны для ТЕКУЩЕГО кадра. Обновление через sceneManager.update
    // (после рендера) даёт покадровый рассинхрон, который проявляется
    // паразитным параллаксом фона при трансляции камеры
    //
    // Кубмапа читается из resourceObserver.sceneBackground ПОКАДРОВО, а не
    // кэшируется в отдельное поле — НЕ из-за смены сценария посреди жизни
    // этого меша (её не бывает: смена сценария разбирает граф целиком и
    // строит его заново, см. SceneManager.dispose/initialize, так что новый
    // BlackHole получает уже свежий фон при конструировании). Причина проще:
    // остальные uniforms и так обновляются каждый кадр здесь же, заводить
    // отдельный кэш под одну ссылку было бы лишней сущностью без выигрыша
    this.onBeforeRender = (_renderer: WebGLRenderer, _scene: Scene, camera: Camera): void => {
      this.material.update(this, camera, this.resourceObserver.sceneBackground, this._epoch)
    }
  }

  /**
   * Кастомный рейкаст: кликабелен только видимый образ дыры (clickRadiusUnits),
   * а не вся bounding-сфера зоны симуляции. Геометрия меша в рейкасте
   * не участвует — пересечение считается аналитически
   */
  public raycast(raycaster: Raycaster, intersects: Intersection[]): void {
    BlackHole._clickSphere.center.setFromMatrixPosition(this.matrixWorld)
    BlackHole._clickSphere.radius = this.parameters.clickRadiusUnits

    const point: Vector3 | null = raycaster.ray.intersectSphere(BlackHole._clickSphere, BlackHole._clickPoint)

    if (point) {
      const distance: number = raycaster.ray.origin.distanceTo(point)

      if (distance >= raycaster.near && distance <= raycaster.far) {
        intersects.push({ distance, point: point.clone(), object: this })
      }
    }
  }

  public updateObject(ctx: UpdateContext): void {
    // per-frame обновление материала живёт в onBeforeRender; сюда кэшируем
    // только эпоху кадра (updateObject вызывается до рендера). Камера — не
    // ctx.camera, а аргумент самого onBeforeRender: three передаёт туда
    // камеру АКТУАЛЬНОГО render-прохода, что важно и для сценариев вне
    // главного цикла (напр. Postprocessing.captureScreenshot рендерит вне цикла кадра)
    this._epoch = ctx.epoch
  }
}

export { BlackHole }

