import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { readFile, writeFile } from 'node:fs/promises'
import { createHash } from 'node:crypto'
const baselineOnly=process.argv.includes('--red'),prefix='benchmark-results/heavy-scenes/',date='2026-10-26'
const output=`${prefix}black-hole-background-parity-${baselineOnly?'red':'green'}-${date}.json`
Object.assign(process.env,{VITE_FS_DRIVER:'local',VITE_FILE_BUCKET:'browser-test',VITE_S3_URL:'https://s3.invalid',VITE_SHOW_STATS_PANEL:'false',VITE_SKY_SOURCE:'gaia'})
const helper=await readFile(prefix+'black-hole-background-baseline-'+date+'.glsl','utf8')
const report={base:'e0073ed3e65e0e083b4a9f87714f6d1a11936feb',startedAt:new Date().toISOString(),rows:[],warnings:[],errors:[],failedRequests:[],outcome:'failed'}
let server,browser,phase='setup'
try{
  server=await createServer({server:{host:'127.0.0.1',port:8094,strictPort:true,hmr:false}});await server.listen()
  for(const samples of [0,4]){
    let prior
    for(const pass of ['baseline','candidate']){
      phase=pass
      // An identical shader reused within one browser can return cached HLSL
      // without the original compiler warning. Each phase gets a fresh process.
      browser=await chromium.launch({channel:'chrome',headless:true})
      const page=await browser.newPage({viewport:{width:640,height:360},deviceScaleFactor:1})
      page.on('pageerror',error=>report.errors.push(error.stack??error.message))
      page.on('console',message=>{if(message.type()==='warning')report.warnings.push({phase,samples,text:message.text()});if(message.type()==='error')report.errors.push({phase,samples,text:message.text()})})
      page.on('requestfailed',request=>report.failedRequests.push({phase,samples,url:request.url(),failure:request.failure()?.errorText}))
      await page.goto('http://127.0.0.1:8094/tests/browser/harness.html')
      const row=await page.evaluate(async({helper,samples,pass})=>{
        const module=await import('/benchmark-results/heavy-scenes/black-hole-background-parity-2026-10-26.browser.ts')
        return module.compareBackground(helper,samples,pass)
      },{helper,samples,pass})
      if(/SwiftShader|llvmpipe|software/i.test(row.environment.renderer))throw Error('Unexpected software renderer')
      const images=row.images.map(data=>Buffer.from(data,'base64'))
      for(let index=0;index<images.length;index++){
        const bytes=images[index],image=row.rows[index]
        if(bytes.length!==image.bytes||createHash('sha256').update(bytes).digest('hex')!==image.sha256)throw Error('Capture transfer mismatch')
        image.different=0;image.maxError=0
        if(prior){if(prior[index]?.length!==bytes.length)throw Error('Image lengths differ');for(let i=0;i<bytes.length;i++){const delta=Math.abs(bytes[i]-prior[index][i]);if(delta)image.different++;image.maxError=Math.max(image.maxError,delta)}}
      }
      if(pass==='baseline')prior=images
      delete row.images
      report.rows.push(row)
      console.log(pass,samples,JSON.stringify({metrics:row.metrics,images:row.rows.length,different:row.rows.reduce((sum,r)=>sum+r.different,0),programs:row.programs.map(p=>({linked:p.linked,log:p.log,translatedLength:p.translated?.length}))}))
      await browser.close();browser=null
    }
  }
  if(report.errors.length||report.failedRequests.length)throw Error('Browser errors')
  if(report.rows.some(row=>row.rows.some(image=>image.different)))throw Error('Production images changed')
