async function source(path,json=true){const bytes=await readFile(path);provenance.push({path,bytes:bytes.length,sha256:hash(bytes)});return json?JSON.parse(decode(bytes)):decode(bytes)}
const parseFile=async path=>JSON.parse(decode(await readFile(path)))
function splitHelper(source){const start=source.indexOf('    vec3 sampleBackground('),end=source.indexOf('\n    }\n',start);check(start>=0&&end>start,'Missing shader helper');return{before:source.slice(0,start),helper:source.slice(start,end+6),after:source.slice(end+6)}}
const flowTokens=s=>s.replace(/\/\/[^\n]*/g,'').replace(/\belse\b/g,'').replace(/[{}\s]/g,'')
function browser(report){
  const rows=[]
  function walk(suite){
    for(const spec of suite.specs??[])for(const test of spec.tests)for(const result of test.results){
      const a=Object.fromEntries((result.attachments??[]).filter(a=>a.body&&a.contentType==='application/json').map(a=>[a.name,JSON.parse(Buffer.from(a.body,'base64').toString())]))
      rows.push({title:spec.title,status:result.status,retry:result.retry,durationMs:result.duration,errors:result.errors,environment:a['webgl-environment'],probe:a['probe-result'],diagnostics:a['browser-diagnostics']})
    }
    for(const child of suite.suites??[])walk(child)
  }
  walk(report);return{stats:report.stats,errors:report.errors,rows}
}
const sampleWarning=text=>/\bX4000\b.*\bf_sampleBackground\b/.test(text)
function diagnostics(run,red=false){
  check(!run.errors.length,'Runner errors')
  for(const row of run.rows){
    const d=row.diagnostics
    if(row.probe)check(d&&row.environment,'Missing probe diagnostics')
    if(!d)continue
    check(!d.pageErrors.length&&!d.console.some(x=>x.type==='error'),'Browser errors')
    check(d.failedRequests.every(q=>row.title==='native texture fetch cancellation and cube orientation'&&/^http:\/\/127\.0\.0\.1:\d+\/held-texture\.png$/.test(q.url)&&q.failure==='net::ERR_ABORTED'),'Failed request')
    check(d.warningClassifications.every(x=>['expected-context-restoration-cleanup','gpu-readback-performance'].includes(x.category)||red&&sampleWarning(x.text)),'Unexpected warning')
  }
}
function cleanSuite(run,count){diagnostics(run);check(run.stats.expected===count&&!run.stats.unexpected&&!run.stats.skipped&&!run.stats.flaky&&run.rows.length===count&&run.rows.every(r=>r.status==='passed'&&r.retry===0&&!r.errors.length),'Incomplete/failed browser suite')}
function analytic(run){const row=run.rows.find(r=>r.title==='black hole background sampling');check(row?.probe?.status==='passed','Missing analytic result');const cases=row.probe.result.results;check(cases.length===25&&new Set(cases.map(c=>c.name)).size===25,'Incomplete analytic cases');for(const c of cases)check(c.mismatchedComponents===0&&same(c.firstPixel,c.expected),'Analytic pixels differ')}
function parity(run,red){
  check(run.base===base&&!run.errors.length&&!run.failedRequests.length&&run.rows.length===4,'Incomplete parity run')
  check(same(run.rows.map(r=>[r.phase,r.multisampling]),[['baseline',0],['candidate',0],['baseline',4],['candidate',4]]),'Wrong parity phases')
  check(run.warnings.length===(red?4:2)&&run.warnings.every(w=>sampleWarning(w.text)&&(red||w.phase==='baseline')),'Parity warning gate')
  for(let i=0;i<4;i++){
    const row=run.rows[i],original=run.rows[i-i%2],warn=red||row.phase==='baseline'
    check(!/SwiftShader|llvmpipe|software/i.test(row.environment.renderer)&&row.rows.length===8&&row.programs.length===1,'Wrong parity environment/captures')
