    check(same(row.metrics,original.metrics),'Production scene metrics changed')
    for(let j=0;j<8;j++){const image=row.rows[j];check(image.index===j&&image.bytes===640*360*4&&!image.different&&!image.maxError&&/^[0-9a-f]{64}$/.test(image.sha256)&&image.sha256===original.rows[j].sha256,'Production images differ')}
